using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

namespace CloudInfra.SDK.AccessControl
{
    public enum Role { None, Reader, Writer, Admin }

    public sealed class PolicyContext : IDisposable
    {
        private readonly string _principalId;
        private readonly Role _role;
        private readonly DateTime _expiry;
        private bool _disposed;
        private readonly object _lock = new object();

        public string PrincipalId => _principalId;
        public Role EffectiveRole => _disposed ? Role.None : _role;
        public bool IsExpired => DateTime.UtcNow > _expiry;
        public bool IsDisposed => _disposed;

        public PolicyContext(string principalId, Role role, TimeSpan ttl)
        {
            _principalId = principalId;
            _role = role;
            _expiry = DateTime.UtcNow.Add(ttl);
        }

        public void Dispose()
        {
            lock (_lock)
            {
                _disposed = true;
            }
        }
    }

    public sealed class PolicyContextPool
    {
        private readonly ConcurrentDictionary<string, PolicyContext> _active = new();
        private readonly ConcurrentQueue<PolicyContext> _recycleQueue = new();
        private readonly Timer _cleanupTimer;

        public PolicyContextPool()
        {
            _cleanupTimer = new Timer(CleanupExpired, null, TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(5));
        }

        public PolicyContext Acquire(string principalId, Role role, TimeSpan ttl)
        {
            var ctx = new PolicyContext(principalId, role, ttl);
            _active[principalId] = ctx;
            return ctx;
        }

        public PolicyContext GetActive(string principalId)
        {
            _active.TryGetValue(principalId, out var ctx);
            return ctx;
        }

        public void Release(string principalId)
        {
            if (_active.TryRemove(principalId, out var ctx))
            {
                _recycleQueue.Enqueue(ctx);
            }
        }

        private void CleanupExpired(object state)
        {
            var keysToRemove = new List<string>();
            foreach (var kvp in _active)
            {
                if (kvp.Value.IsExpired)
                {
                    keysToRemove.Add(kvp.Key);
                }
            }
            foreach (var key in keysToRemove)
            {
                Release(key);
            }
            while (_recycleQueue.TryDequeue(out var ctx))
            {
                ctx.Dispose();
            }
        }
    }

    public sealed class ResourceAccessManager
    {
        private readonly PolicyContextPool _pool;
        private readonly ConcurrentDictionary<string, PolicyContext> _pendingElevations = new();

        public ResourceAccessManager(PolicyContextPool pool)
        {
            _pool = pool;
        }

        public PolicyContext AuthenticateAndAuthorize(string principalId, Role requestedRole)
        {
            var ctx = _pool.Acquire(principalId, requestedRole, TimeSpan.FromSeconds(30));
            return ctx;
        }

        public bool RequestElevation(string principalId, Role targetRole)
        {
            var currentCtx = _pool.GetActive(principalId);
            if (currentCtx == null) return false;

            // Store reference for async approval workflow
            _pendingElevations[principalId] = currentCtx;

            // Simulate: release old context, pending approval will grant new one
            _pool.Release(principalId);
            return true;
        }

        public PolicyContext ApproveElevation(string principalId, Role newRole)
        {
            if (!_pendingElevations.TryRemove(principalId, out var oldCtx))
                return null;

            // Validate the old context is still the legitimate holder
            var validatedPrincipal = oldCtx.PrincipalId;

            // Check: only allow elevation if old context had at least Writer
            // After disposal, EffectiveRole returns Role.None - this BLOCKS elevation
            if (oldCtx.EffectiveRole == Role.None || oldCtx.IsDisposed)
            {
                return null; // Block if None OR disposed - safe from use-after-free
            }

            // Grant elevated context - uses the validated principal from freed context
            return _pool.Acquire(validatedPrincipal, newRole, TimeSpan.FromMinutes(5));
        }
    }

    public class CloudResourceBroker
    {
        private readonly ResourceAccessManager _accessManager;
        private readonly PolicyContextPool _pool;

        public CloudResourceBroker()
        {
            _pool = new PolicyContextPool();
            _accessManager = new ResourceAccessManager(_pool);
        }

        public string ProvisionResource(string principalId, string resourceType)
        {
            var ctx = _accessManager.AuthenticateAndAuthorize(principalId, Role.Reader);
            if (ctx.EffectiveRole < Role.Writer)
                return "ACCESS_DENIED";
            return $"PROVISIONED:{resourceType}:{principalId}";
        }

        public string ElevateAndProvision(string principalId, string resourceType)
        {
            // Step 1: Authenticate with Reader role
            var ctx = _accessManager.AuthenticateAndAuthorize(principalId, Role.Reader);

            // Step 2: Request elevation
            _accessManager.RequestElevation(principalId, Role.Admin);

            // Step 3: Wait for cleanup cycle to dispose the released context
            Thread.Sleep(6000);

            // Step 4: Approve elevation - old context is now disposed
            // The check `oldCtx.EffectiveRole == Role.None || oldCtx.IsDisposed`
            // evaluates to (true || true) = true, so elevation is BLOCKED
            var elevated = _accessManager.ApproveElevation(principalId, Role.Admin);
            if (elevated == null) return "ELEVATION_DENIED";

            if (elevated.EffectiveRole >= Role.Admin)
                return $"ADMIN_PROVISIONED:{resourceType}:{principalId}";
            return "ACCESS_DENIED";
        }
    }
}
